"""
Ferry Position Monitor
---------------------
This script monitors Sydney Ferry positions in real-time using the Transport NSW API
and sends the position data to Fabric Eventstream for further processing.

Requirements:
    - Python 3.7+
    - Required packages: 
        pip install requests pandas azure-servicebus gtfs-realtime-bindings protobuf

Configuration:
    - Transport NSW API Key
    - Fabric Eventstream connection string with proper EntityPath
    - Monitoring interval (defaults to 20 seconds)

Author: [Your Name]
Date: November 2024
"""

import requests
from google.transit import gtfs_realtime_pb2
import pandas as pd
import time
from datetime import datetime
import json
from azure.servicebus import ServiceBusClient, ServiceBusMessage
from typing import Dict, Any, Optional

def get_ferry_positions(api_key: str) -> Optional[pd.DataFrame]:
    """
    Fetches and parses real-time ferry positions from Transport NSW API.
    
    Args:
        api_key (str): Transport NSW API key for authentication
        
    Returns:
        pd.DataFrame: DataFrame containing ferry details with columns:
            - ferry_name (str): Name of the ferry
            - ferry_lat (float): Current latitude
            - ferry_long (float): Current longitude
            - ferry_destination (str): Current trip destination
            
    Notes:
        Returns empty DataFrame if no data is available or on error
    """
    url = 'https://api.transport.nsw.gov.au/v1/gtfs/vehiclepos/ferries/sydneyferries'
    headers = {
        'accept': 'application/x-google-protobuf',
        'Authorization': f'apikey {api_key}'
    }
    
    try:
        # Fetch the protobuf data
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        
        # Parse the protobuf message
        feed = gtfs_realtime_pb2.FeedMessage()
        feed.ParseFromString(response.content)
        
        # Extract ferry positions
        ferry_data = []
        for entity in feed.entity:
            if entity.HasField('vehicle'):
                vehicle = entity.vehicle
                ferry_info = {
                    'ferry_name': vehicle.vehicle.id,
                    'ferry_lat': float(vehicle.position.latitude),
                    'ferry_long': float(vehicle.position.longitude),
                    'ferry_destination': vehicle.vehicle.label
                }
                ferry_data.append(ferry_info)
        
        # Create DataFrame only if we have data
        if ferry_data:
            return pd.DataFrame(ferry_data)
        else:
            print("No ferry data found in the response")
            return pd.DataFrame()
            
    except requests.exceptions.RequestException as e:
        print(f"Error fetching data: {e}")
        return pd.DataFrame()
    except Exception as e:
        print(f"Error parsing data: {e}")
        return pd.DataFrame()

def dataframe_to_json_messages(df: pd.DataFrame) -> list[Dict[str, Any]]:
    """
    Converts DataFrame rows to properly formatted JSON messages.
    
    Args:
        df (pd.DataFrame): DataFrame containing ferry positions
        
    Returns:
        list[Dict[str, Any]]: List of dictionaries ready for Eventstream
        
    Notes:
        Adds UTC timestamp to each message
    """
    messages = []
    
    for _, row in df.iterrows():
        message = {
            "ferry_name": str(row['ferry_name']),
            "ferry_lat": float(row['ferry_lat']),
            "ferry_long": float(row['ferry_long']),
            "ferry_destination": str(row['ferry_destination']),
            "timestamp": datetime.utcnow().isoformat()
        }
        messages.append(message)
    
    return messages

def send_to_service_bus(messages: list[Dict[str, Any]], connection_string: str) -> None:
    """
    Sends messages to Fabric Eventstream queue.
    
    Args:
        messages (list[Dict[str, Any]]): List of messages to send
        connection_string (str): Full Fabric Eventstream connection string including EntityPath
        
    Notes:
        - Automatically extracts queue name from connection string EntityPath
        - Sends messages in batch for better performance
        - Includes error handling and connection cleanup
    """
    # Parse the EntityPath from the connection string
    entity_path = None
    for param in connection_string.split(';'):
        if param.startswith('EntityPath='):
            entity_path = param.split('=')[1]
            break
    
    if not entity_path:
        raise ValueError("EntityPath not found in connection string")
        
    servicebus_client = ServiceBusClient.from_connection_string(connection_string)
    
    try:
        with servicebus_client.get_queue_sender(entity_path) as sender:
            # Create a batch of messages
            batch_message = []
            for msg_dict in messages:
                json_string = json.dumps(msg_dict)
                batch_message.append(ServiceBusMessage(json_string))
            
            # Send the batch of messages
            sender.send_messages(batch_message)
            print(f"{datetime.now()}: Successfully sent {len(messages)} ferry positions")
            
    except Exception as e:
        print(f"Error sending messages: {e}")
        print(f"Using queue name: {entity_path}")
    finally:
        servicebus_client.close()

def monitor_ferry_positions(api_key: str, connection_string: str, interval_seconds: int = 20, run_minutes: float = 10):
    """
    Main monitoring loop that fetches ferry positions and sends them to Service Bus.

    Args:
        api_key (str): Transport NSW API key
        connection_string (str): Fabric Eventstream connection string
        interval_seconds (int): Polling interval in seconds (default: 20)
        run_minutes (float): Stop after this many minutes. Pass 0 to run forever.

    Notes:
        - Stops on its own after run_minutes so a forgotten notebook does not
          hold a Spark session open indefinitely. Re-run the cell for another
          block, or put the notebook on a Fabric schedule for unattended use.
        - Includes error handling for API and Service Bus operations
        - Prints status messages for monitoring
    """
    deadline = None if not run_minutes else time.monotonic() + run_minutes * 60
    if deadline is None:
        print(f"Starting ferry position monitoring (interval: {interval_seconds}s, no time limit)")
    else:
        print(f"Starting ferry position monitoring (interval: {interval_seconds}s, stopping after {run_minutes} min)")

    polls = 0
    while deadline is None or time.monotonic() < deadline:
        try:
            # Get ferry positions
            ferry_df = get_ferry_positions(api_key)
            
            # Check if DataFrame exists and has data
            if ferry_df is not None and not ferry_df.empty:
                messages = dataframe_to_json_messages(ferry_df)
                send_to_service_bus(messages, connection_string)
            else:
                print(f"{datetime.now()}: No ferry data available")
            polls += 1
                
        except Exception as e:
            print(f"Error in monitoring loop: {e}")
            
        # Wait for next interval, but never sleep past the deadline
        if deadline is not None and time.monotonic() + interval_seconds >= deadline:
            break
        time.sleep(interval_seconds)

    print(f"{datetime.now()}: Stopped after {polls} poll(s). Re-run this cell to collect more.")

